class Solution:
    def countUnderCap(self, factors: List[int], cap: int) -> int:
        n, total = len(factors), 0
        for i in range(n):
            product = 1
            for j in range(i, n):
                product *= factors[j]
                if product >= cap:
                    break
                total += 1
        return total

