class Solution {
    public long countUnderCap(int[] factors, int cap) {
        int n = factors.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            long product = 1;
            for (int j = i; j < n; j++) {
                product *= factors[j];
                if (product >= cap) break;
                total++;
            }
        }
        return total;
    }
}

