class Solution:
    def countUnderCap(self, factors: List[int], cap: int) -> int:
        if cap <= 1:
            return 0
        product, left, total = 1, 0, 0
        for i, f in enumerate(factors):
            product *= f
            while product >= cap:
                product //= factors[left]
                left += 1
            total += i - left + 1
        return total

