class Solution {
    public long countUnderCap(int[] factors, int cap) {
        if (cap <= 1) return 0;
        long product = 1, total = 0;
        int left = 0;
        for (int i = 0; i < factors.length; i++) {
            product *= factors[i];
            while (product >= cap) product /= factors[left++];
            total += i - left + 1;
        }
        return total;
    }
}

